/**
 * Retrieves and normalizes the effective progress percentage for a given story.
 * Ensures the value is within valid bounds (0-100) for subsequent calculations.
 *
 * @param {object} story - The Story entity.
 * @param {number | null | undefined} story.progress - The progress value of the story.
 * @returns {number} The normalized progress value (0-100).
 */
export const calculateStoryProgress = (story) => {
  const progress = story?.progress;

  if (typeof progress !== 'number' || progress === null || progress < 0) {
    return 0;
  }
  if (progress > 100) {
    return 100;
  }
  return progress;
};

/**
 * Derives the status of an entity (Story or Epic) based on its progress percentage and a manual `isBlocked` flag.
 * The `BLOCKED` status takes precedence over all other derived statuses.
 *
 * @param {number} progress - The progress percentage (0-100).
 * @param {boolean} isBlocked - Flag indicating if the entity is blocked.
 * @returns {'BLOCKED' | 'NOT_STARTED' | 'IN_PROGRESS' | 'COMPLETED'} The derived status.
 */
export const deriveStatus = (progress, isBlocked) => {
  if (isBlocked) {
    return 'BLOCKED';
  }
  if (progress === 0) {
    return 'NOT_STARTED';
  }
  if (progress === 100) {
    return 'COMPLETED';
  }
  return 'IN_PROGRESS'; // progress is between 1 and 99 inclusive
};

/**
 * Calculates the overall progress percentage for an Epic based on the arithmetic mean of its associated Stories' progress.
 *
 * @param {Array<object> | null | undefined} stories - An array of Story entities belonging to the epic.
 * @returns {number} The rounded average progress (0-100).
 */
export const calculateEpicProgress = (stories) => {
  if (!Array.isArray(stories) || stories.length === 0) {
    return 0;
  }

  let totalProgress = 0;
  for (const story of stories) {
    totalProgress += calculateStoryProgress(story);
  }

  const averageProgress = totalProgress / stories.length;
  return Math.round(averageProgress);
};

/**
 * Calculates the overall progress percentage for a Project based on the arithmetic mean of its associated Epics' progress.
 * Each Epic's progress is calculated dynamically from its stories.
 *
 * @param {Array<object> | null | undefined} epics - An array of Epic entities belonging to the project.
 * @param {Array<object> | null | undefined} epics[].stories - An array of Story entities belonging to the epic.
 * @returns {number} The rounded average progress (0-100).
 */
export const calculateProjectProgress = (epics) => {
  if (!Array.isArray(epics) || epics.length === 0) {
    return 0;
  }

  let totalEpicProgress = 0;
  for (const epic of epics) {
    // Ensure epic.stories is an array, even if empty or null
    const currentEpicProgress = calculateEpicProgress(epic?.stories || []);
    totalEpicProgress += currentEpicProgress;
  }

  const averageProjectProgress = totalEpicProgress / epics.length;
  return Math.round(averageProjectProgress);
};

/**
 * Derives the status of a Project based on its progress percentage,
 * respecting a manually set `PAUSED` status unless the project is 100% complete.
 *
 * @param {number} progress - The progress percentage (0-100).
 * @param {'PAUSED' | 'ACTIVE' | 'PLANNING' | 'COMPLETED'} currentStatus - The current manual status of the project.
 * @returns {'PAUSED' | 'ACTIVE' | 'PLANNING' | 'COMPLETED'} The derived project status.
 */
export const deriveProjectStatus = (progress, currentStatus) => {
  if (progress === 100) {
    return 'COMPLETED';
  }
  if (currentStatus === 'PAUSED') {
    return 'PAUSED';
  }
  if (progress === 0) {
    return 'PLANNING';
  }
  return 'ACTIVE'; // progress is between 1 and 99 inclusive
};